import{_ as e,o as a,c as s,a2 as i}from"./chunks/framework.BXzK3EA4.js";const c=JSON.parse('{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md","lastUpdated":1787871741000}'),o={name:"guide/getting-started.md"};function r(l,t,n,p,h,d){return a(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><p>Beholder is a macOS desktop app that shows you exactly what your React Native app sends over the network — without touching a single line of your project.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li>macOS on Apple Silicon</li><li><a href="https://developer.android.com/studio" target="_blank" rel="noreferrer">Android Studio</a> with: <ul><li><strong>platform-tools</strong> (adb) — the emulator and cmdline-tools must be installed</li><li>An emulator AVD with a <strong>Google APIs</strong> image (not Google Play)</li></ul></li><li>Node 18+ and Rust for building from source</li></ul><div class="warning custom-block"><p class="custom-block-title">Google Play images will not work</p><p>Google Play emulator images refuse <code>adb root</code>, which Beholder needs to install its certificate. The emulator creation wizard only offers Google APIs images for this reason. Existing Play-based AVDs show a <code>no root</code> badge.</p></div><h2 id="install-from-source" tabindex="-1">Install from source <a class="header-anchor" href="#install-from-source" aria-label="Permalink to &quot;Install from source&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/JavierGaMa/beholder.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> beholder</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tauri</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>The first Rust build takes a couple of minutes. Subsequent builds are fast.</p><h2 id="your-first-capture" tabindex="-1">Your first capture <a class="header-anchor" href="#your-first-capture" aria-label="Permalink to &quot;Your first capture&quot;">​</a></h2><ol><li><strong>Pick a target</strong> — the emulator dropdown in the command bar lists your AVDs. Selecting a stopped emulator launches it and opens the onboarding stepper, which waits for boot and prepares everything for you.</li><li><strong>Press Capture</strong> — Beholder installs its CA as a system certificate (into the Conscrypt apex on Android 14+), starts a local MITM proxy, and points the emulator&#39;s global proxy at it.</li><li><strong>Use your app</strong> — open your React Native app on the emulator. Requests appear in real time.</li></ol><div class="tip custom-block"><p class="custom-block-title">Metro timing</p><p>A React Native app in development makes no network requests until the Metro bundle loads. An empty request list right after launch is normal — wait for the bundle, then interact with the app.</p></div><h2 id="what-non-invasive-means" tabindex="-1">What &quot;non-invasive&quot; means <a class="header-anchor" href="#what-non-invasive-means" aria-label="Permalink to &quot;What &quot;non-invasive&quot; means&quot;">​</a></h2><ul><li>No code changes, no interceptors, no manifest tweaks in your app</li><li>The emulator&#39;s global proxy is reverted when you stop capture or quit Beholder</li><li>Stale proxies pointing at dead ports are cleaned automatically on launch</li><li>The CA stays installed between sessions for fast startup; &quot;Full cleanup&quot; in Settings removes it</li></ul><h2 id="stop-or-quit-safely" tabindex="-1">Stop or quit safely <a class="header-anchor" href="#stop-or-quit-safely" aria-label="Permalink to &quot;Stop or quit safely&quot;">​</a></h2><p>Stopping capture or closing the app always reverts the emulator proxy. If Beholder is killed without a clean exit, the next launch detects and clears any dead proxy automatically.</p>`,15)])])}const g=e(o,[["render",r]]);export{c as __pageData,g as default};
